-- =====================================================================
-- Spazio Design · Cotizador · Float 10 mm en mesas altas (29/10/2026)
-- Todo lo que va en laminado 5+5 también se hace en float 10 mm en incoloro, gris y bronce.
-- (Ratonas, auxiliares y estanterías ya lo tenían.) Publica una versión nueva de cada receta.
-- Generado por scripts/cotizador/recetas_catalogo.py. Se puede correr de nuevo.
-- =====================================================================

create or replace function pg_temp.publicar_receta(p_nombre text, p_categoria text, p_def jsonb, p_nota text) returns text
language plpgsql as $$
declare
  v_prod uuid;
  v_pub public.cot_recetas%rowtype;
  v_bor uuid;
  v_id uuid;
  v_ver integer;
begin
  select id into v_prod from public.cot_productos where lower(nombre) = lower(p_nombre) and activo;
  if v_prod is null then
    insert into public.cot_productos (nombre, categoria_id)
    values (p_nombre, (select id from public.cot_categorias where nombre = p_categoria))
    returning id into v_prod;
  end if;
  select * into v_pub from public.cot_recetas where producto_id = v_prod and estado = 'publicada';
  if found and v_pub.definicion = p_def then return p_nombre || ': sin cambios'; end if;
  if found then update public.cot_recetas set estado = 'archivada' where id = v_pub.id; end if;
  select id into v_bor from public.cot_recetas where producto_id = v_prod and estado = 'borrador';
  if v_bor is not null then
    update public.cot_recetas set definicion = p_def, nota = p_nota where id = v_bor;
    update public.cot_recetas set estado = 'publicada', publicado_en = now() where id = v_bor;
    v_id := v_bor;
  else
    select coalesce(max(version), 0) + 1 into v_ver from public.cot_recetas where producto_id = v_prod;
    insert into public.cot_recetas (producto_id, version, estado, definicion, nota, publicado_en)
    values (v_prod, v_ver, 'publicada', p_def, p_nota, now()) returning id into v_id;
  end if;
  update public.cot_productos set receta_publicada_id = v_id where id = v_prod;
  insert into public.cot_receta_insumos (receta_id, insumo_id)
  select v_id, i.id from public.cot_insumos i
  where p_def::text like '%''' || i.codigo || '''%' or p_def::text like '%"' || i.codigo || '"%'
  on conflict do nothing;
  select version into v_ver from public.cot_recetas where id = v_id;
  return p_nombre || ': publicada la versión ' || v_ver;
end $$;
select pg_temp.publicar_receta('Mesa Sol', 'Mesas de comedor', '{"orden": ["D", "H", "color", "combinada", "color_bases", "espesor", "tipo_vidrio", "insertos"], "entradas": {"D": {"tipo": "medida", "nombre": "Diámetro", "def": 100}, "H": {"tipo": "medida", "nombre": "Alto", "def": 75}, "color": {"tipo": "opcion", "nombre": "Color", "atributo": "color", "def": "incoloro"}, "combinada": {"tipo": "opcion", "nombre": "Bases de otro color", "permitidos": ["no", "si"], "def": "no"}, "color_bases": {"tipo": "opcion", "nombre": "Color de las bases", "atributo": "color", "def": "incoloro", "mostrarSi": "combinada == ''si''"}, "espesor": {"tipo": "opcion", "nombre": "Vidrio", "permitidos": ["5+5", "6+6", "8+8", "10+10"], "def": "5+5"}, "insertos": {"tipo": "opcion", "nombre": "Insertos", "permitidos": ["no", "si"], "def": "no"}, "tipo_vidrio": {"tipo": "opcion", "nombre": "Tipo de vidrio", "permitidos": ["laminado 5+5", "float 10 mm"], "def": "laminado 5+5", "mostrarSi": "espesor == ''5+5'' && (en(color, ''incoloro'', ''gris'', ''bronce'') || (combinada == ''si'' && en(color_bases, ''incoloro'', ''gris'', ''bronce'')))"}}, "lineas": [{"id": "tapa", "nombre": "Tapa redonda", "regla": "m2", "variante": {"espesor": "''10''", "composicion": "espesor", "color": "color"}, "ancho": "D", "largo": "D", "insumoFormula": "si(espesor == ''5+5'' && tipo_vidrio == ''float 10 mm'' && en(color, ''incoloro'', ''gris'', ''bronce''), ''vidrio-float'', ''vidrio-laminado'')"}, {"id": "bases", "nombre": "Base en cruz", "regla": "m2", "variante": {"espesor": "''10''", "composicion": "espesor", "color": "si(combinada == ''si'', color_bases, color)"}, "ancho": "redondear(D * 0.5)", "largo": "H - 1", "cantidad": "2", "insumoFormula": "si(espesor == ''5+5'' && tipo_vidrio == ''float 10 mm'' && en(si(combinada == ''si'', color_bases, color), ''incoloro'', ''gris'', ''bronce''), ''vidrio-float'', ''vidrio-laminado'')"}, {"id": "forma", "nombre": "Recargo por forma", "regla": "porcentaje", "porcentaje": "aj.recargo_forma", "sobre": ["tapa"], "nota": "Piezas con forma o puntas redondeadas: 20%"}, {"id": "ajuste", "nombre": "Ajuste", "regla": "porcentaje", "porcentaje": "aj.ajuste_vidpro", "sobre": ["bases"], "nota": "Mesa alta: 20% solo sobre las bases"}, {"id": "uv", "nombre": "Pegado UV", "regla": "ml", "insumo": "pegado-uv", "variante": {"tipo_vidrio": "si(espesor == ''5+5'' && tipo_vidrio == ''float 10 mm'' && en(color, ''incoloro'', ''gris'', ''bronce'') && espesor == ''5+5'' && tipo_vidrio == ''float 10 mm'' && en(si(combinada == ''si'', color_bases, color), ''incoloro'', ''gris'', ''bronce''), ''float'', ''laminado'')"}, "metros": "(2 * (H - 1)) / 100"}, {"id": "insertos_alta", "nombre": "Insertos de aluminio", "regla": "fijo", "condicion": "insertos == ''si''", "insumoFormula": "si(espesor == ''5+5'', ''insertos-mesa-alta-10'', ''insertos-mesa-alta-12'')"}, {"id": "doble_faz", "nombre": "Cinta doble faz", "regla": "fijo", "condicion": "insertos == ''no''", "insumo": "cinta-doble-faz"}]}'::jsonb, 'Proporciones del cotizador de la web (sin plano)');
